{
  "query": "mutation CreateEvent($input: CreateEventInput!) { createEvent(input: $input) { id title status locationId startAt endAt participants { id email } } }",
  "variables": {
    "input": {
      "title": "Event 1",
      "locationId": "budapest-office",
      "startAt": "2026-05-25T09:00:00.000Z",
      "endAt": "2026-05-25T10:00:00.000Z",
      "participantEmails": ["A@test.com", "B@test.com"]
    }
  }
}

{
  "query": "query { events { id title status locationId location { id name } startAt endAt participants { id email } createdAt updatedAt } }"
}

{
  "query": "query Event($id: ID!) { event(id: $id) { id title status locationId location { id name } startAt endAt participants { id email } createdAt updatedAt } }",
  "variables": {
    "id": "{{eventId}}"
  }
}

{
  "query": "mutation UpdateEvent($id: ID!, $input: UpdateEventInput!) { updateEvent(id: $id, input: $input) { id title status locationId startAt endAt participants { id email } } }",
  "variables": {
    "id": "{{eventId}}",
    "input": {
      "title": "Event 1 Updated",
      "locationId": "debrecen-office",
      "startAt": "2026-05-26T11:00:00.000Z",
      "endAt": "2026-05-26T12:00:00.000Z",
      "participantEmails": ["A@test.com", "C@test.com"]
    }
  }
}

{
  "query": "mutation PublishEvent($id: ID!) { publishEvent(id: $id) { id title status participants { email } } }",
  "variables": {
    "id": "{{eventId}}"
  }
}

